from PIL import Image,ImageDraw
import os
p='/app/output/raise_obs/last'; fs=sorted(os.listdir(p)); out=Image.new('RGB',(960,760),'white'); d=ImageDraw.Draw(out)
for i,n in enumerate(fs):
 im=Image.open(p+'/'+n); im.thumbnail((480,360)); x=i%2*480;y=i//2*380;out.paste(im,(x,y+20));d.text((x+3,y+3),n,fill='black')
out.save('/app/output/raise_montage.jpg')
PY",yield_time_ms:10000,max_output_tokens:100});
text(r.output);
const v=await tools.view_image({path:"/app/output/raise_montage.jpg"}); image(v.image_url);

